ALTER TABLE public.signup_links ADD COLUMN outfit_min_price numeric, ADD COLUMN outfit_max_price numeric;
ALTER TABLE public.signup_links ADD CONSTRAINT signup_link_price_bounds CHECK ((outfit_min_price IS NULL OR outfit_min_price >= 0) AND (outfit_max_price IS NULL OR outfit_max_price >= 0) AND (outfit_min_price IS NULL OR outfit_max_price IS NULL OR outfit_max_price >= outfit_min_price));
CREATE OR REPLACE FUNCTION public.member_outfit_allowed(_member uuid, _outfit uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM invite_codes c JOIN outfits o ON o.id=_outfit AND o.invite_id=c.invite_id LEFT JOIN families f ON f.id=c.family_id LEFT JOIN signup_links l ON l.id=f.signup_link_id WHERE c.id=_member AND ((l.outfit_min_price IS NULL AND l.outfit_max_price IS NULL) OR (o.price_inr IS NOT NULL AND (l.outfit_min_price IS NULL OR o.price_inr>=l.outfit_min_price) AND (l.outfit_max_price IS NULL OR o.price_inr<=l.outfit_max_price)))) $$;
REVOKE ALL ON FUNCTION public.member_outfit_allowed(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.member_outfit_allowed(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guest_outfit_ids(_member uuid) RETURNS SETOF uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM invite_codes c WHERE c.id=_member AND is_my_household(c.household,c.invite_id)) THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN QUERY SELECT o.id FROM outfits o JOIN invite_codes c ON c.id=_member AND c.invite_id=o.invite_id WHERE member_outfit_allowed(c.id,o.id) OR EXISTS(SELECT 1 FROM reservations r WHERE r.outfit_id=o.id AND r.member_code_id=c.id); END $$;
REVOKE ALL ON FUNCTION public.guest_outfit_ids(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.guest_outfit_ids(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_member_outfit_range() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.outfit_id=OLD.outfit_id AND NEW.member_code_id IS NOT DISTINCT FROM OLD.member_code_id THEN RETURN NEW; END IF; IF is_celebration_host(NEW.invite_id) THEN RETURN NEW; END IF; IF NEW.member_code_id IS NULL THEN NEW.member_code_id:=resolve_member_code(NEW.guest_id,NEW.invite_id,NEW.guest_name); END IF; IF NEW.member_code_id IS NULL OR NOT EXISTS(SELECT 1 FROM invite_codes c WHERE c.id=NEW.member_code_id AND c.invite_id=NEW.invite_id AND is_my_household(c.household,c.invite_id)) THEN RAISE EXCEPTION 'Choose a member of your own family'; END IF; IF NOT member_outfit_allowed(NEW.member_code_id,NEW.outfit_id) THEN RAISE EXCEPTION 'This outfit is not in the collection offered to this person'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reservations_price_range BEFORE INSERT OR UPDATE OF outfit_id,member_code_id ON public.reservations FOR EACH ROW EXECUTE FUNCTION public.enforce_member_outfit_range();
CREATE POLICY "Guests read code-linked family selections" ON public.reservations FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.invite_codes c WHERE c.id=member_code_id AND c.invite_id=reservations.invite_id AND public.is_my_household(c.household,c.invite_id)));
CREATE OR REPLACE FUNCTION public.host_choose_outfit(_member uuid,_outfit uuid,_size text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c invite_codes%ROWTYPE; o outfits%ROWTYPE; ev events%ROWTYPE; account uuid; rid uuid; BEGIN SELECT * INTO c FROM invite_codes WHERE id=_member FOR UPDATE; IF NOT FOUND OR NOT is_celebration_host(c.invite_id) THEN RAISE EXCEPTION 'Only this celebration''s hosts can choose'; END IF; SELECT * INTO o FROM outfits WHERE id=_outfit AND invite_id=c.invite_id FOR UPDATE; IF NOT FOUND OR o.event_id IS NULL OR NOT o.is_available THEN RAISE EXCEPTION 'This outfit is unavailable'; END IF; SELECT * INTO ev FROM events WHERE id=o.event_id; IF ev.outfit_selection=false OR NOT EXISTS(SELECT 1 FROM household_event_invites h WHERE h.household=c.household AND h.invite_id=c.invite_id AND h.event_id=o.event_id AND h.outfit_selection) THEN RAISE EXCEPTION 'This person is not offered outfits for this event'; END IF; IF NOT member_outfit_allowed(c.id,o.id) THEN RAISE EXCEPTION 'This outfit is outside this person''s assigned collection'; END IF; IF c.gender IS NOT NULL AND c.gender<>o.gender THEN RAISE EXCEPTION 'Choose an outfit from this person''s wardrobe'; END IF; IF EXISTS(SELECT 1 FROM reservations r JOIN outfits x ON x.id=r.outfit_id WHERE r.member_code_id=c.id AND x.event_id=o.event_id) THEN RAISE EXCEPTION 'This person already has an outfit for this event; existing choices are preserved'; END IF; account:=c.claimed_by; IF account IS NULL THEN SELECT claimed_by INTO account FROM invite_codes WHERE invite_id=c.invite_id AND household=c.household AND claimed_by IS NOT NULL LIMIT 1; END IF; account:=coalesce(account,auth.uid()); INSERT INTO reservations(invite_id,outfit_id,guest_id,guest_name,member_code_id,status,size_choice,build_size,build_garment) VALUES(c.invite_id,o.id,account,c.guest_name,c.id,'confirmed',nullif(trim(_size),''),nullif(trim(_size),''),o.garment_type) RETURNING id INTO rid; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.host_choose_outfit(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.host_choose_outfit(uuid,uuid,text) TO authenticated;